 1 | using System;
 2 | using Cedar.Tests.TestSupport;
 3 | using Cedar.Types;
 4 | using Xunit;
 5 | 
 6 | namespace Cedar.Tests.Types;
 7 | 
 8 | public sealed class CedarDatetimeTests
 9 | {
10 |     [Fact]
11 |     public void ConstructorStoresMilliseconds()
12 |     {
13 |         CedarDatetime value = new(42);
14 | 
15 |         Assert.Equal(42, value.Value);
16 |     }
17 | 
18 |     [Fact]
19 |     public void ParseAcceptsDateOnlyForm()
20 |     {
21 |         CedarAssert.CedarText(CedarDatetime.Parse("1970-01-01"), "datetime(\"1970-01-01T00:00:00.000Z\")");
22 |     }
23 | 
24 |     [Fact]
25 |     public void ParseAcceptsZuluTime()
26 |     {
27 |         CedarAssert.CedarText(CedarDatetime.Parse("1970-01-01T01:01:01Z"), "datetime(\"1970-01-01T01:01:01.000Z\")");
28 |     }
29 | 
30 |     [Fact]
31 |     public void ParseAcceptsMillisecondPrecision()
32 |     {
33 |         CedarAssert.CedarText(CedarDatetime.Parse("1970-01-01T00:00:00.042Z"), "datetime(\"1970-01-01T00:00:00.042Z\")");
34 |     }
35 | 
36 |     [Fact]
37 |     public void ParseAddsPositiveOffset()
38 |     {
39 |         CedarAssert.CedarText(CedarDatetime.Parse("1970-01-01T00:00:00+0100"), "datetime(\"1970-01-01T01:00:00.000Z\")");
40 |     }
41 | 
42 |     [Fact]
43 |     public void ParseAppliesNegativeOffset()
44 |     {
45 |         CedarAssert.CedarText(CedarDatetime.Parse("1970-01-01T01:00:00-0100"), "datetime(\"1970-01-01T00:00:00.000Z\")");
46 |     }
47 | 
48 |     [Fact]
49 |     public void ParseRejectsShortInput()
50 |     {
51 |         Assert.Throws<FormatException>(() => CedarDatetime.Parse("1970-01"));
52 |     }
53 | 
54 |     [Fact]
55 |     public void ParseRejectsInvalidDate()
56 |     {
57 |         Assert.Throws<FormatException>(() => CedarDatetime.Parse("2024-02-30T00:00:00Z"));
58 |     }
59 | 
60 |     [Fact]
61 |     public void ParseRejectsInvalidTimeZone()
62 |     {
63 |         Assert.Throws<FormatException>(() => CedarDatetime.Parse("1970-01-01T00:00:00V"));
64 |     }
65 | 
66 |     [Fact]
67 |     public void EqualValuesAreEqual()
68 |     {
69 |         CedarAssert.Equal(new CedarDatetime(42), CedarDatetime.Parse("1970-01-01T00:00:00.042Z"));
70 |     }
71 | 
72 |     [Fact]
73 |     public void DifferentValuesAreNotEqual()
74 |     {
75 |         CedarAssert.NotEqual(new CedarDatetime(42), new CedarDatetime(43));
76 |     }
77 | 
78 |     [Fact]
79 |     public void HashCodeIsStable()
80 |     {
81 |         CedarAssert.HashStable(new CedarDatetime(1234));
82 |     }
83 | 
84 |     [Fact]
85 |     public void JsonRoundTripUsesDatetimeExtension()
86 |     {
87 |         CedarDatetime expected = CedarDatetime.Parse("1970-01-01T00:00:00.042Z");
88 | 
89 |         string json = CedarJson.SerializeData(expected);
90 |         ICedarData actual = CedarJson.DeserializeData(json);
91 | 
92 |         Assert.Equal("{\"__extn\":{\"fn\":\"datetime\",\"arg\":\"1970-01-01T00:00:00.042Z\"}}", json);
93 |         CedarAssert.Equal(expected, Assert.IsType<CedarDatetime>(actual));
94 |     }
95 | }

